    teemsiio.foreach(teemsiio => tee_axireg.foreach(tee_axireg => teemsiio <> tee_axireg.module.msiio))
    ree_mNode.out.head._1 <> ree_sNode.in.head._1
    tee_mNode.foreach(_.out.head._1 <> tee_sNode.get.in.head._1)
  }
}

