  def apply(cond: Bool, reset: Bool, n: Int): (UInt, Bool) = {
    val c = new CounterWithReset(n)
    var wrap: Bool = null
    when (cond) { wrap = c.inc() }
    when (reset) { c.reset() }
    (c.value, cond && wrap)
  }

  def apply(cond: Bool, reset: Bool, max: UInt): (UInt, Bool) = {
