object CounterOneShot {
    def apply(m:BigInt, en:Bool, continue:Bool = false.B): (UInt, Bool) = {
        val w = log2Ceil(m)
        val cnt = RegInit(0.U(w.W))
        val wrap = cnt === (m-1).U
