        RegInit(false.B)
    }
    val toggle_b = withClockAndReset(io.toClock, io.toReset) {
        RegInit(0.U((nStages+1).W))
    }
    withClock(io.toClock) {
        toggle_b := (toggle_b << 1) | toggle_a
    }

    withClock(io.fromClock) {
        when(io.triggerIn) {
            toggle_a := !toggle_a
        }
    }
    io.triggerOut := toggle_b(nStages, nStages - 1).xorR
}

