        private def shiftLeft(n: Int): SInt = {
            val w: Int = x.getWidth
            (x(w - 1) ## (x(w - 2, 0) << n).take(w - 1)).asSInt
        }

        private def shiftRight(n: Int): SInt = {
            val w: Int = x.getWidth
            (x >> n).asSInt.extend(w)
        }

        private def shiftLeft(n: UInt): SInt = {
            val w: Int = x.getWidth
            (x(w - 1) ## (x(w - 2, 0) << n).take(w - 1)).asSInt
        }

