        def pokeUserIfExist(user: BigInt): Option[BigInt] = {
            x match {
                case y: StrHasUser => {
                    y.user match {
                        case u: UInt => u.poke(user)
                        case u: SInt => u.poke(user)
                        case _ => y.user.poke(user.asUInt)
