        private def matchPoint(that: FixPoint): (SInt, SInt, Int) = {
            val fw = math.max(this.fw, that.fw)
            val lBits = (this.bits << (fw - this.fw)).asSInt
            val rBits = (that.bits << (fw - that.fw)).asSInt
