        _rs2 += 0
        _ret += (if (signed == 0) rmem.toSigned(1 << (3+mod)) else rmem.toUnsigned(1 << (3+mod))).toUnsigned()
      }
      case StoreTest => {
        _mode += (1 << 3) + mod
        _rd  += 0
        _rs2 += random32()
