  printf(
    "Counter: %d, OP: 0x%x, A: 0x%x, B: 0x%x, OUT: 0x%x ?= 0x%x, SUM: 0x%x ?= 0x%x\n",
    cntr,
    dut.io.alu_op,
    dut.io.A,
    dut.io.B,
    dut.io.out,
    out._1,
    dut.io.sum,
    out._2
  )
}

class ALUTests extends AnyFlatSpec with ChiselScalatestTester with Formal {
  "ALUSimple" should "pass" in {
    test(new AluTester(new AluSimple(32))).runUntilStop()
  }
  "AluArea" should "pass" in {
    test(new AluTester(new AluArea(32))).runUntilStop()
  }
  "AluArea" should "be equivalent to AluSimple" in {
    // since there is no state (registers/memory) in the ALU, a single cycle check is enough to prove equivalence
    verify(new AluEquivalenceCheck(new AluArea(32)), Seq(BoundedCheck(1)))
  }
}

class AluEquivalenceCheck(other: => Alu) extends Module {
  val dut = Module(other)
  val ref = Module(new AluSimple(dut.width))

  // arbitrary inputs
  val io = IO(chiselTypeOf(dut.io))

  // connect the same inputs to both modules (the outputs will be overwritten to always connect to the reference)
  dut.io <> io; ref.io <> io

  // check to ensure that outputs are the same
  assert(ref.io.out === dut.io.out, "out: expected: %d, actual: %d", ref.io.out, dut.io.out)
  assert(ref.io.sum === dut.io.sum, "sum: %d, actual: %d", ref.io.sum, dut.io.sum)
}

  assert(dut.io.taken === out)
  printf(
    "Counter: %d, BrType: 0x%x, rs1: 0x%x, rs2: 0x%x, Taken: %d ?= %d\n",
    cntr,
    dut.io.br_type,
    dut.io.rs1,
    dut.io.rs2,
    dut.io.taken,
    out
  )
}

class BrCondTests extends AnyFlatSpec with ChiselScalatestTester with Formal {
  "BrCondSimple" should "pass" in {
    test(new BrCondTester(new BrCondSimple(32))).runUntilStop()
  }
  "BrCondArea" should "pass" in {
    test(new BrCondTester(new BrCondArea(32))).runUntilStop()
  }
  "BrCondArea" should "be equivalent to BrCondSimple" in {
    // since there is no state (registers/memory) in the BrCond, a single cycle check is enough to prove equivalence
    verify(new BrCondEquivalenceCheck(new BrCondArea(32)), Seq(BoundedCheck(1)))
  }
}

class BrCondEquivalenceCheck(other: => BrCond) extends Module {
  val dut = Module(other)
  val ref = Module(new BrCondSimple(dut.xlen))

  // arbitrary inputs
  val io = IO(chiselTypeOf(dut.io))

  // connect the same inputs to both modules (the outputs will be overwritten to always connect to the reference)
  dut.io <> io; ref.io <> io

  // check to ensure that outputs are the same
  assert(ref.io.taken === dut.io.taken, "taken: expected: %d, actual: %d", ref.io.taken, dut.io.taken)
}

