          val first_write_idx = PriorityEncoder(write_signals)
          // printf("#first_read_idx: %b, first_write_idx: %b\n", first_read_idx, first_write_idx)

          when(read_signals.asUInt > 0.U && first_read_idx <= first_write_idx) {
