        rs = rs_in,
        rd = rd_in,
        rt = rt_in,
        decoded_reg_write_enable = prevCycleData.decoded_reg_write_enable,
        decoded_reg_input_mux = prevCycleData.decoded_reg_input_mux,
        decoded_immediate = prevCycleData.decoded_immediate,
