class SchedulerSpec extends AnyFreeSpec with Matchers {
  "Test scheduler" - {
    "should match model behavior with random inputs" in {
      val ThreadsPerBlock: Int = 4
      simulate(new Scheduler(ThreadsPerBlock)) { dut =>
        dut.reset.poke(true.B)
        dut.clock.step()
        dut.reset.poke(false.B)
        dut.clock.step()

        var cnt            = 0
        val rng            = new scala.util.Random(42) // 42 is the seed for reproducibility
        val schedulerModel = new SchedulerModel(ThreadsPerBlock)

        def randomLsuState(rng: scala.util.Random): LSUState.Type = {
          val v = rng.nextInt(4)
          v match {
            case 0 => LSUState.IDLE
            case 1 => LSUState.REQUESTING
            case 2 => LSUState.WAITING
            case 3 => LSUState.DONE
          }
        }

        while (cnt < 10000) {
          // Generate random inputs
          val start              = rng.nextBoolean()
          val mem_read_enable    = rng.nextBoolean()
          val mem_write_enable   = rng.nextBoolean()
          val decoded_ret        = rng.nextBoolean()
          val (fetcher_state, _) = FetcherState.safe(rng.nextInt(3).U)              // Assuming 3 states: IDLE, FETCHING, FETCHED
          val lsu_state          = Array.fill(ThreadsPerBlock)(randomLsuState(rng)) // Assuming 4 states in LSUState
          val next_pc            = Array.fill(ThreadsPerBlock)(rng.nextInt(256))    // 8-bit PC values

          // Poke inputs
          dut.io.start.poke(start.B)
          dut.io.mem_rw_enable.read_enable.poke(mem_read_enable.B)
          dut.io.mem_rw_enable.write_enable.poke(mem_write_enable.B)
          dut.io.decoded_ret.poke(decoded_ret.B)
          dut.io.fetcher_state.poke(fetcher_state)
          for (i <- 0 until ThreadsPerBlock) {
            dut.io.lsu_state(i).poke(lsu_state(i))
            dut.io.next_pc(i).poke(next_pc(i).U)
          }

          dut.clock.step()

          // Update model
          schedulerModel.update(
            start = start,
            mem_read_enable = mem_read_enable,
            mem_write_enable = mem_write_enable,
            decoded_ret = decoded_ret,
            fetcher_state = fetcher_state,
            lsu_state = lsu_state,
            next_pc = next_pc
          )

          // Compare model with DUT
          dut.io.current_pc.expect(schedulerModel.current_pc.U)
          assert(dut.io.core_state.peekValue().asBigInt == schedulerModel.core_state.litValue)
          dut.io.done.expect(schedulerModel.done.B)

          cnt += 1
        }
      }
    }
  }
